"""Generate docs/STAGE_TOOLS.md from agent/phases.py (never hand-edit the output): which MCP tools each stage and each
specialist may call. A test keeps the file in step with the code."""

from __future__ import annotations

import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT / "backend"))

from faultline.agent import phases as P  # noqa: E402

OUT = ROOT / "docs" / "STAGE_TOOLS.md"


def render() -> str:
    lines = ["# Stage and specialist tool whitelists", "",
             "> GENERATED by `scripts/gen_stage_tools.py` from `backend/faultline/agent/phases.py`. Each model call is "
             "offered only its stage's tools (`llm_toolset`); a call outside the list returns an error, is logged and is "
             "recorded as a refused ToolCall. Post-verdict tools are never offered to the investigator. "
             "Internal tools build engine-written scratch graphs and are never hosted on MCP.", "",
             "| stage | tools |", "|---|---|"]
    for stage, tools in P.PHASE_TOOLS.items():
        lines.append(f"| {stage.value if hasattr(stage, 'value') else stage} | "
                     + (", ".join(f"`{t}`" for t in tools) or "—") + " |")
    lines += ["", "| specialist | tools |", "|---|---|"]
    for role, tools in P.SPECIALIST_TOOLS.items():
        lines.append(f"| {role} | " + ", ".join(f"`{t}`" for t in tools) + " |")
    lines += ["", f"**Post-verdict (code-driven, never offered to the model):** {', '.join(f'`{t}`' for t in sorted(P.POST_VERDICT))}",
              "", f"**Internal (not hosted on MCP):** {', '.join(f'`{t}`' for t in sorted(P.INTERNAL_TOOLS))}", ""]
    return "\n".join(lines)


if __name__ == "__main__":
    OUT.write_text(render())
    print(f"wrote {OUT.relative_to(ROOT)}")
